/** SDK-compiled native bridge against authored resource/producer/actor records only. */
public final class NativeHeldBridgeTest {
 private static int checks;private static void check(boolean value,String why){if(!value)throw new AssertionError(why);checks++;}
 private static IsoPlayer actor;private static Frame frame;private static ModelSlotRenderData slot;private static SkinningData skin;private static InventoryItem item;private static NativeHeldAccess access;private static Matrix4f[] output;
 private static void setup(){
  Main.ready=true;Engine.enabled=Engine.worldPresent=true;Engine.playspaceYaw=0;Engine.originPose=null;zombie.GameTime.paused=false;zombie.network.GameClient.client=zombie.network.GameServer.server=false;VrControls.supportedPistol=null;NativeRig.posedAt=0;WorldItemModelDrawer.status=ItemModelRenderer.RenderStatus.Ready;WorldItemModelDrawer.calls=0;ItemModelRenderer.hasModel=true;viewpoint.models.Models.capturing=false;viewpoint.models.Models.owns=0;
  skin=new SkinningData();skin.boneIndices.put("Bip01_Prop2",0);skin.boneIndices.put("Bip01_Prop1",1);actor=new IsoPlayer();IsoPlayer.players=new IsoPlayer[]{actor};IsoPlayer.instance=actor;actor.animation.skin=skin;item=new InventoryItem();item.container=actor.inventory;actor.inventory.items.add(item);actor.secondary=item;
  frame=new Frame();frame.camX=100;frame.camY=200;frame.camZ=3;slot=new ModelSlotRenderData();slot.character=actor;var instance=new ModelInstance();instance.model.tag=skin;var data=new ModelInstanceRenderData();data.modelInstance=instance;slot.modelData.add(data);frame.scene.models.append(instance,new ModelMesh(),new zombie.core.textures.Texture(),null,new Matrix4f().translation(10,20,30).scale(-1.5f,1.5f,1.5f).get(new float[16]),true);
  var hand=new XrBackend.Hand(new Math3.Pose(new Math3.Vec(0,0,0),new Math3.Quat(0,0,0,1)),null,true,0,0,0);Engine.latestInput=new XrBackend.Frame(System.nanoTime(),true,true,null,List.of(),hand,new XrBackend.Hand(hand.grip(),null,true,0,0,0));
  WorldItemModelDrawer.nextMesh=new ModelMesh();WorldItemModelDrawer.nextTexture=new zombie.core.textures.Texture();zombie.scripting.ScriptManager.instance=new zombie.scripting.ScriptManager();output=new Matrix4f[]{new Matrix4f().translation(1,2,3),new Matrix4f().translation(4,5,6)};access=new NativeHeldAccess();NativeHeldFallback.adapterForTest(access);NativeHeldFallback.configureForTest(true);
 }
 private static NativeHeldFallback.Capture capture(){return access.begin(frame,slot,actor,1);}
 private static void run(){NativeHeldScopeAdvice.enter(frame,slot,actor);NativeHeldPoseAdvice.exit(skin,output);NativeRig.posedAt=System.nanoTime();NativeHeldScopeAdvice.exit(null);NativeHeldRenderAdvice.exit(frame,null);}
 private static void noDraw(String why,Runnable change){setup();change.run();run();check(WorldItemModelDrawer.calls==0&&frame.scene.models.count()==1,why);}
 public static void main(String[] args)throws Exception{
  setup();var c=capture();check(c!=null&&c.actor()==actor&&c.input()==Engine.latestInput&&c.scene()==frame.scene,"actual bridge binds exact current actor/input/scene");check(c.leftProp()==0&&c.rightProp()==1,"exact selected Prop2/Prop1 physical side order");check(access.eligible(c,new NativeHeldFallback.Slot(0,item)),"world-only declared CordlessPhone admitted");float[] before=frame.scene.models.numeric().clone();run();check(frame.scene.models.count()==2&&WorldItemModelDrawer.calls==1&&viewpoint.models.Models.owns==1,"successful original-producer double creates one receipt before remount");check(Arrays.equals(Arrays.copyOf(before,68),Arrays.copyOf(frame.scene.models.numeric(),68)),"all original native rows immutable");check(frame.scene.models.numeric()[80]==8.5f&&frame.scene.models.numeric()[81]==23&&frame.scene.models.numeric()[82]==34.5f,"phone row mounted on actual final left socket");check(frame.scene.models.numeric()[95]==.2f,"native bounds radius preserved");check(!viewpoint.models.Models.capturing,"borrowed native capture destination restored");check(NativeHeldFallback.status().contains("Prop2"),"successful exact receipt visible in status");
  setup();actor.primary=item;actor.secondary=null;run();check(frame.scene.models.numeric()[80]==4f&&frame.scene.models.numeric()[81]==27.5f&&frame.scene.models.numeric()[82]==39f,"primary physical right uses Prop1 without dominant swapping");
  noDraw("SDK readiness missing fails closed",()->Main.ready=false);noDraw("paused native gameplay skips producer",()->zombie.GameTime.paused=true);noDraw("multiplayer physical fallback guarded",()->zombie.network.GameClient.client=true);noDraw("world unavailable skips producer",()->Engine.worldPresent=false);noDraw("dead actor skipped",()->actor.dead=true);noDraw("timed/action previews own native pose",()->actor.timed=true);noDraw("native supported pistol keeps all pose authority",()->VrControls.supportedPistol=new InventoryItem());noDraw("native existing hand model has priority",()->actor.secondaryHandModel=new ModelInstance());noDraw("other held item type never promoted",()->item.type="Base.Remote");noDraw("declared held model never substituted",()->item.heldModel="CordlessPhone");noDraw("two-handed item rejected",()->item.both=true);noDraw("same item in both slots rejected",()->actor.primary=item);noDraw("heavy prop native drop priority",()->item.heavy=true);noDraw("replace-primary attachment priority",()->item.tag=true);noDraw("ground item cannot be rendered as inventory-held",()->item.worldItem=new zombie.iso.objects.IsoWorldInventoryObject());noDraw("transferred item ownership rejected",()->item.container=new zombie.inventory.ItemContainer());noDraw("removed inventory identity rejected",()->actor.inventory.items.remove(item));noDraw("wrong native world alias rejected",()->item.world="Other");noDraw("native script attachments remain authoritative",()->zombie.scripting.ScriptManager.instance.script.attachments=1);noDraw("unknown model scale rejected",()->zombie.scripting.ScriptManager.instance.script.scale=.5f);noDraw("changed native script mesh rejected",()->zombie.scripting.ScriptManager.instance.script.mesh="Other");
  setup();c=capture();Engine.latestInput=new XrBackend.Frame(System.nanoTime(),true,true,null,List.of(),Engine.latestInput.left(),Engine.latestInput.right());check(!access.current(c),"new equal-hand input frame cannot borrow native capture");setup();c=capture();frame.camX+=1;check(!access.current(c),"camera change invalidates source placement");setup();c=capture();Engine.playspaceYaw=1;check(!access.current(c),"recenter/yaw change invalidates socket");setup();c=capture();frame.scene.models.mutateInstance(0,new ModelInstance());check(!access.current(c),"pooled model instance reuse rejected");setup();c=capture();frame.scene.models.numeric()[12]+=1;check(!access.current(c),"actor palette base mutation rejected");setup();c=capture();actor.animation.skin=new SkinningData();check(!access.current(c),"skin generation change rejected");
  setup();WorldItemModelDrawer.status=ItemModelRenderer.RenderStatus.Loading;run();check(frame.scene.models.count()==1&&NativeHeldFallback.status().contains("not ready"),"loading original resource supplies no visual");setup();WorldItemModelDrawer.nextMesh.ready=false;run();check(frame.scene.models.count()==1&&WorldItemModelDrawer.calls==1,"unready mesh appended receipt safely discarded");setup();WorldItemModelDrawer.nextMesh.path=new zombie.asset.AssetPath("Other.fbx");run();check(frame.scene.models.count()==1,"wrong resource identity discarded");setup();WorldItemModelDrawer.nextTexture.name="Other.png";run();check(frame.scene.models.count()==1,"wrong original material identity discarded");setup();WorldItemModelDrawer.nextMesh.skinningData=skin;run();check(frame.scene.models.count()==1,"skinned source is not a rigid phone fallback");
  setup();NativeHeldScopeAdvice.enter(frame,slot,actor);NativeHeldPoseAdvice.exit(skin,output);NativeRig.posedAt=System.nanoTime();NativeHeldScopeAdvice.exit(null);NativeHeldRenderAdvice.exit(frame,new IllegalStateException());check(WorldItemModelDrawer.calls==0,"failed native model snapshot never appends");Main.ready=false;boolean denied=false;try{NativeHeldFallback.configure(true);}catch(IllegalStateException expected){denied=true;}check(denied&&!NativeHeldFallback.enabled(),"SDK availability loss clears configured state before reporting failure");NativeHeldFallback.configureForTest(false);System.out.println("Native held resource bridge: "+checks+" checks passed; authored native records only, no original Game/XR methods");
 }
}
